package dev.pedro.learning.ecommerce.inventory;
import dev.pedro.learning.ecommerce.inventory.application.InventorySagaService; import dev.pedro.learning.ecommerce.inventory.domain.*; import dev.pedro.learning.ecommerce.inventory.event.*; import dev.pedro.learning.ecommerce.inventory.inbox.InboxEventRepository; import dev.pedro.learning.ecommerce.inventory.outbox.OutboxEventRepository; import io.quarkus.narayana.jta.QuarkusTransaction; import io.quarkus.test.junit.QuarkusTest; import jakarta.inject.Inject; import org.junit.jupiter.api.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*;
@QuarkusTest class InventoryIdempotencyTest { static final UUID PRODUCT=UUID.fromString("11111111-1111-1111-1111-111111111111"); @Inject InventorySagaService saga; @Inject InventoryItemRepository items; @Inject InventoryReservationRepository reservations; @Inject InboxEventRepository inbox; @Inject OutboxEventRepository outbox;
 @BeforeEach void reset(){QuarkusTransaction.requiringNew().run(()->{outbox.deleteAll();inbox.deleteAll();reservations.deleteAll();items.deleteAll();InventoryItem i=new InventoryItem();i.productId=PRODUCT;i.availableQuantity=10;i.reservedQuantity=0;items.persist(i);});}
 @Test void duplicateOrderCreatedReservesOnlyOnce(){UUID eventId=UUID.randomUUID(),corr=UUID.randomUUID(),order=UUID.randomUUID();var event=new EventEnvelope<>(eventId,corr,"OrderCreated",Instant.now(),1,new OrderCreatedPayload(order,PRODUCT,2,new BigDecimal("10.00"),new BigDecimal("20.00"),"a@b.com"));saga.onOrderCreated(event);saga.onOrderCreated(event);InventoryItem item=items.findById(PRODUCT);assertEquals(8,item.availableQuantity);assertEquals(2,item.reservedQuantity);assertEquals(1,inbox.count());assertEquals(1,outbox.count("type","StockReserved"));}
}
